#!/usr/bin/env bash
# Regenerates the images in stipple/README.md. Run from the repository root;
# needs ffmpeg, uv and curl.
set -euo pipefail

out=stipple/assets
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
mkdir -p "$out"

cargo build -q -p tui-stipple --release
bin=target/release/stipple
raster() { uv run -q stipple/tools/raster.py "$@" --round; }

# An abstract plasma loop, generated by ffmpeg: shimmer and glitches on.
ffmpeg -v error -y -f lavfi \
  -i "color=black:s=320x240:r=15,format=rgb24,geq=r='128+127*sin(X/19+T*1.7)*cos(Y/27-T*1.1)':g='128+127*sin((X+Y)/31+T*1.3)':b='128+127*cos(hypot(X-W/2\,Y-H/2)/15-T*2.1)'" \
  -t 4 -pix_fmt yuv420p "$work/plasma.mp4"
"$bin" --dump "$work/plasma.txt" --size 64x24 --frames 45 --detail octants "$work/plasma.mp4"
raster "$work/plasma.txt" "$out/plasma.gif" --cell 10x20 --fps 15

# A mossy forest (photo: Jorge Láscar, CC BY 2.0), beside its render.
curl -sSL -A "tui-stipple-readme" -o "$work/forest.jpg" \
  "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Lascar_Exuberant_vegetation_%28Montane_rainforests_biome%29_%284460864208%29.jpg/1280px-Lascar_Exuberant_vegetation_%28Montane_rainforests_biome%29_%284460864208%29.jpg"
ffmpeg -v error -y -i "$work/forest.jpg" -vf scale=800:-2 -q:v 4 "$out/forest-photo.jpg"
"$bin" --dump "$work/forest.txt" --size 100x33 --frames 1 --detail octants --glitch 0 "$work/forest.jpg"
raster "$work/forest.txt" "$out/forest.png" --cell 8x16

# The same crop of the plasma at each level of background detail.
for detail in flat quadrants octants; do
  "$bin" --dump "$work/$detail.txt" --size 64x24 --frames 1 --start 1 --detail "$detail" --glitch 0 "$work/plasma.mp4"
  raster "$work/$detail.txt" "$work/$detail.png" --cell 10x20
done
uv run -q --with pillow python - "$work" "$out/detail.png" <<'EOF'
import sys
from PIL import Image, ImageDraw
work, out = sys.argv[1], sys.argv[2]
names = ["flat", "quadrants", "octants"]
crop = (330, 250, 570, 450)
w, h = crop[2] - crop[0], crop[3] - crop[1]
sheet = Image.new("RGB", (3 * w * 2 + 2 * 12, h * 2 + 28), (24, 24, 32))
draw = ImageDraw.Draw(sheet)
for i, name in enumerate(names):
    tile = Image.open(f"{work}/{name}.png").convert("RGB").crop(crop).resize((w * 2, h * 2), Image.NEAREST)
    x = i * (w * 2 + 12)
    sheet.paste(tile, (x, 28))
    draw.text((x + 4, 6), name, fill=(200, 200, 210))
sheet.save(out)
EOF
ls -la "$out"
